-- Migration 008: Software MR (Software Maintenance Release / Companion Cheatsheets)

CREATE TABLE IF NOT EXISTS software_mr_releases (
    id SERIAL PRIMARY KEY,
    model VARCHAR(100) NOT NULL,
    ole_version VARCHAR(100) DEFAULT '',
    oxm_olm_new_version VARCHAR(100) DEFAULT '',
    ap VARCHAR(100) NOT NULL DEFAULT '',
    cp VARCHAR(100) NOT NULL DEFAULT '',
    csc VARCHAR(100) NOT NULL DEFAULT '',
    ap_mapping VARCHAR(100) DEFAULT '',
    cp_mapping VARCHAR(100) DEFAULT '',
    csc_version_up VARCHAR(100) DEFAULT '',
    status VARCHAR(50) DEFAULT 'DONE',
    pic VARCHAR(100) NOT NULL DEFAULT 'ENDRI',
    release_note_format TEXT DEFAULT '',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    deleted_at TIMESTAMP WITH TIME ZONE
);

CREATE INDEX IF NOT EXISTS idx_software_mr_model ON software_mr_releases(model);
CREATE INDEX IF NOT EXISTS idx_software_mr_pic ON software_mr_releases(pic);
CREATE INDEX IF NOT EXISTS idx_software_mr_created ON software_mr_releases(created_at);

ON CONFLICT (id) DO NOTHING;

SELECT setval('software_mr_releases_id_seq', (SELECT MAX(id) FROM software_mr_releases));
